ACTIONS["derive"] = () => { Store.commit(s => { const r = byId(s.runs, UI.selRun); r.derivation = Derivation.run(r.request.text, r.interpretation.targets, r.interpretation.held, r.excluded || []); r.status = r.derivation.final ? "derived" : "failed"; r.composition = null; Store.log("derivation", r.derivation.final ? `Workflow derived for ${r.id} (${r.derivation.final.length} tasks, ${r.derivation.source})` : `Derivation failed for ${r.id}`, r.id, { final: r.derivation.final, unmet: r.derivation.unmet }); }); render(); };
ACTIONS["confirm-wf"] = () => { Store.commit(s => { const r = byId(s.runs, UI.selRun); r.status = "confirmed"; r.workflowConfirmedAt = new Date().toISOString(); Store.log("workflow-confirmed", `Workflow of ${r.id} confirmed by the requester`, r.id); }); UI.step = 4; render(); };
