    Store.log("repair-applied", `Repair of ${rr.id}: ${choices.filter(Boolean).map(c => c.label).join("; ")}`, rr.id);
    if (rederive) { rr.derivation = Derivation.run(rr.request.text, rr.interpretation.targets, rr.interpretation.held, rr.excluded); Store.log("derivation", rr.derivation.final ? `Workflow re-derived for ${rr.id} after repair` : `Re-derivation failed for ${rr.id}`, rr.id); }
